#!/usr/bin/env node
"use strict";
// Compare two JSON inventories generated by schema-parity-readonly.cjs.
// No database access, external API calls, or mutations.
const fs=require("node:fs");
function compare(dev,prod){
  if(dev.target!=="development"||prod.target!=="production")throw Error("TARGET_LABEL_MISMATCH");
  if(!dev.identity?.db||!prod.identity?.db)throw Error("MISSING_DATABASE_IDENTITY");
  if(!Array.isArray(dev.tables)||!Array.isArray(prod.tables))throw Error("INVALID_TABLE_INVENTORY");
  const unique=(items)=>{const x=new Map();for(const t of items){if(!t||typeof t.name!=="string"||!t.name||x.has(t.name))throw Error("INVALID_OR_DUPLICATE_TABLE");x.set(t.name,t);}return x;};
  const d=unique(dev.tables),p=unique(prod.tables);
  const missing=[...d.keys()].filter(name=>!p.has(name)).sort();
  const extra=[...p.keys()].filter(name=>!d.has(name)).sort();
  const changed=[...d.keys()].filter(name=>p.has(name)&&(d.get(name).kind!==p.get(name).kind||d.get(name).rls!==p.get(name).rls||d.get(name).force_rls!==p.get(name).force_rls)).sort();
  return {status:!dev.schemaExists?"DEVELOPMENT_SOURCE_MISSING":!prod.schemaExists?"PRODUCTION_SCHEMA_MISSING":missing.length||extra.length||changed.length?"SCHEMA_INVENTORY_DIFFERENT":"TABLE_NAMES_AND_RLS_MATCH_ONLY",
    development:{database:dev.identity.db,schemaExists:dev.schemaExists,tableCount:d.size},
    production:{database:prod.identity.db,schemaExists:prod.schemaExists,tableCount:p.size},
    missing,extra,changed,
    caveat:"Matching table names and RLS flags does NOT prove identical columns, constraints, functions, policies, grants, data or runtime identity."};
}
if(require.main===module){
  try{
    if(process.argv.length!==4)throw Error("USAGE: node scripts/release/compare-schema-inventories.cjs development.json production.json");
    const [dev,prod]=process.argv.slice(2).map(path=>JSON.parse(fs.readFileSync(path,"utf8")));
    const result=compare(dev,prod);console.log(JSON.stringify(result,null,2));
    if(result.status!=="TABLE_NAMES_AND_RLS_MATCH_ONLY")process.exitCode=2;
  }catch(e){console.error("SCHEMA_COMPARISON_FAILED:",e.message);process.exitCode=1;}
}
module.exports={compare};
